const action=ai.action||'help', d=ai.draft&&typeof ai.draft==='object'?ai.draft:{};
const ref=req.text.match(/\bC-\d{6,}\b/i)?.[0]?.toUpperCase()||'';
const isDraft=['create','update','brief'].includes(action);
const content_id=isDraft&&action==='create'?`C-${Date.now().toString().slice(-8)}`:ref;
const need_image=!!(ai.need_image&&d.visual_prompt);
const status=action==='approve'?'approved':action==='reject'?'rejected':isDraft?'pending_approval':'';
let reply=ai.reply||'Commande reçue.'; if(action==='create') reply+=`\n\nRéférence : *${content_id}*\nRépondez : approuver ${content_id}, modifier ${content_id} : …, ou rejeter ${content_id}.`;
if(['approve','reject','update'].includes(action)&&!content_id){reply='Indiquez la référence, par exemple : approuver C-12345678.'; ai.action='help';}
return [{json:{...req,action:ai.action||action,reply,content_id,status,title:d.title||'',caption:d.caption||'',hashtags:d.hashtags||'',visual_prompt:d.visual_prompt||'',platforms:d.platforms||'Facebook, Instagram',need_image,image_url:''}}];

