const base = $('Fusionner brouillon final').first().json;
let ai = {};
try { ai = JSON.parse($json.choices?.[0]?.message?.content ?? '{}'); } catch { ai = {}; }
const brand = $('Lire profil entreprise').first().json || {};
const colors = [brand.primary_color, brand.secondary_color, brand.accent_color].filter(Boolean).join(', ');
const stylePrefix = 'flat vector illustration, clean minimalist design, single clear visual metaphor, no text, no words, no letters, no logo, no UI, no dashboard';
const rawPrompt = ai.image_prompt || base.visual_prompt || 'a simple flat illustration representing growth and success';
const finalPrompt = `${stylePrefix}, ${rawPrompt}, brand colors ${colors || 'vibrant and professional'}, high quality social media graphic, award-winning editorial illustration style`;
const hardNegative = 'text, words, letters, typography, watermark, signature, logo, UI, dashboard, screen, chart, graph, blurry, low quality, deformed, extra limbs, cluttered, busy composition, photorealistic, noisy background';
const negative = ai.negative_prompt ? `${ai.negative_prompt}, ${hardNegative}` : hardNegative;
const aspect = ai.aspect === 'portrait' ? 'portrait' : 'square';
const width = aspect === 'portrait' ? 1080 : 1080;
const height = aspect === 'portrait' ? 1350 : 1080;
const seed = Math.floor(Math.random()*1000000);
const image_url = `https://image.pollinations.ai/prompt/${encodeURIComponent(finalPrompt)}?model=flux&width=${width}&height=${height}&seed=${seed}&nologo=true&enhance=true&negative=${encodeURIComponent(negative)}`;
return [{json:{...base, visual_prompt_final: finalPrompt, visual_prompt_negative: negative, image_url}}];

let html = '';
try { html = typeof $json.data === 'string' ? $json.data : ($json.body || ''); } catch { html = ''; }
if (!html && typeof $json === 'string') html = $json;
let text = String(html)
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();
text = text.slice(0, 700);
if (!text) text = "Nuklear est une agence digitale : conception et developpement de produits web/mobile, design UX/UI, identite visuelle, et externalisation IT.";
return [{json:{...$('Lire profil entreprise').first().json, site_text:text}}];

const base = $json;
const brand = $('Lire profil entreprise').first().json || {};
const cloud = brand.cloudinary_cloud_name;
const rawImage = base.image_url;
if (!cloud || !rawImage) { return [{json: base}]; }
const primary = String(brand.primary_color || '#1A1A2E').replace('#','');
const title = (base.title || '').slice(0, 60);
const baseTransform = 'w_1080,h_1080,c_fill,q_auto,f_auto';
const segments = [baseTransform];
if (title) {
  const textLayer = `l_text:Arial_58_bold:${encodeURIComponent(title)},co_rgb:FFFFFF,b_rgb:${primary},g_south,y_50,w_960,c_fit`;
  segments.push(`${textLayer}/fl_layer_apply`);
}
if (brand.logo_url) {
  const logoLayer = `l_fetch:${encodeURIComponent(brand.logo_url)},g_north_east,x_36,y_36,w_130,fl_relative`;
  segments.push(`${logoLayer}/fl_layer_apply`);
}
const transform = segments.join('/');
const finalUrl = `https://res.cloudinary.com/${cloud}/image/fetch/${transform}/${encodeURIComponent(rawImage)}`;
return [{json: {...base, image_url_ai_only: rawImage, image_url: finalUrl}}];

